@@ -0,0 +1,48 @@
+"use client";
+
+import { useEffect, useState } from "react";
+import { MonitorIcon, MoonIcon, SunIcon } from "lucide-react";
+import { applyTheme, readTheme, type Theme } from "@/lib/theme";
+
+const CHOICES: { value: Theme; label: string; icon: typeof SunIcon }[] = [
+  { value: "system", label: "System", icon: MonitorIcon },
+  { value: "light", label: "Light", icon: SunIcon },
+  { value: "dark", label: "Dark", icon: MoonIcon },
+];
+
+export function ThemeRow() {
+  const [theme, setTheme] = useState<Theme>("system");
+  useEffect(() => setTheme(readTheme()), []);
+  const pick = (t: Theme) => {
+    setTheme(t);
+    applyTheme(t);
+  };
+  return (
+    <div className="flex items-center justify-between gap-4 py-3">
+      <div>
+        <p className="text-sm font-medium">Theme</p>
+        <p className="text-xs text-muted-foreground/70">Follows the system unless you choose.</p>
+      </div>
+      <div role="radiogroup" aria-label="Theme" className="flex rounded-lg border p-0.5">
+        {CHOICES.map((c) => (
+          <button
+            key={c.value}
+            type="button"
+            role="radio"
+            aria-checked={theme === c.value}
+            onClick={() => pick(c.value)}
+            className={theme === c.value ? "rounded-md bg-primary px-2.5 py-1 text-primary-foreground" : "rounded-md px-2.5 py-1 text-muted-foreground"}
+          >
+            <c.icon className="size-4" aria-hidden />
+            <span className="sr-only">{c.label}</span>
+          </button>
+        ))}
+      </div>
+    </div>
+  );
+}
+
+export default ThemeRow;
+
diff --git a/src/lib/theme.ts b/src/lib/theme.ts
new file mode 100644
index 0000000..a7c3e11
--- /dev/null
+++ b/src/lib/theme.ts
@@ -0,0 +1,27 @@
+export type Theme = "system" | "light" | "dark";
+
+const KEY = "theme";
+
+export function readTheme(): Theme {
+  if (typeof window === "undefined") return "system";
+  const v = window.localStorage.getItem(KEY);
+  return v === "light" || v === "dark" ? v : "system";
+}
+
+export function applyTheme(t: Theme) {
+  window.localStorage.setItem(KEY, t);
+  const dark = t === "dark" || (t === "system" && window.matchMedia("(prefers-color-scheme: dark)").matches);
+  document.documentElement.classList.toggle("dark", dark);
+}
+
+// Runs inline in <head> before React: the saved choice wins, then the system.
+export const themeScript = `(function(){try{
+  var t=localStorage.getItem("theme");
+  var d=t==="dark"||(t!=="light"&&matchMedia("(prefers-color-scheme: dark)").matches);
+  if(d)document.documentElement.classList.add("dark");
+}catch(e){}})();`;
+
+export function clearTheme() {
+  window.localStorage.removeItem(KEY);
+  applyTheme("system");
+}
